"""An irreducible standard parabolic subgroup generated by `σ_first:σ_last`."""
struct StandardParabolic
    first::Int
    last::Int
    strands::Int
    function StandardParabolic(first::Integer, last::Integer, strands::Integer)
        1 <= first <= last <= strands-1 ||
            throw(ArgumentError("need 1 ≤ first ≤ last ≤ n-1 for a standard parabolic subgroup"))
        (first == 1 && last == strands-1) &&
            throw(ArgumentError("the full braid group is not a proper parabolic subgroup"))
        new(Int(first), Int(last), Int(strands))
    end
end

StandardParabolic(interval::UnitRange{<:Integer}, strands::Integer) =
    StandardParabolic(first(interval), last(interval), strands)

nstrands(P::StandardParabolic) = P.strands
rank(P::StandardParabolic) = P.last - P.first + 1
puncture_count(P::StandardParabolic) = rank(P) + 1
punctures(P::StandardParabolic) = collect(P.first:P.last+1)
Base.:(==)(a::StandardParabolic, b::StandardParabolic) =
    (a.first, a.last, a.strands) == (b.first, b.last, b.strands)
Base.isequal(a::StandardParabolic, b::StandardParabolic) = a == b
Base.hash(P::StandardParabolic, h::UInt) = hash((P.first, P.last, P.strands), h)
Base.issubset(a::StandardParabolic, b::StandardParabolic) =
    a.strands == b.strands && b.first <= a.first && a.last <= b.last

function Base.show(io::IO, P::StandardParabolic)
    print(io, "A_[$(P.first),$(P.last)] in B$(P.strands)")
end

standard_parabolics(B::BraidGroup) = [StandardParabolic(i, j, B.n) for i in 1:B.n-1 for j in i:B.n-1 if !(i == 1 && j == B.n-1)]
standard_parabolics(n::Integer) = standard_parabolics(BraidGroup(n))

"""The positive central element `z_P`: `Δ_P` at rank 1 and `Δ_P²` above it."""
function central_element(P::StandardParabolic)
    Bp = BraidGroup(puncture_count(P))
    z = rank(P) == 1 ? standard_delta(Bp) : standard_delta(Bp) * standard_delta(Bp)
    shifted = [i + P.first - 1 for i in letters(z)]
    BraidGroup(P.strands)(shifted)
end
z(P::StandardParabolic) = central_element(P)

function flip_parabolic(P::StandardParabolic, exponent::Integer=1)
    iseven(exponent) && return P
    StandardParabolic(P.strands-P.last, P.strands-P.first, P.strands)
end

function _braid_from_parabolic(P::StandardParabolic, candidates, zP::Braid)
    for Q in candidates
        central_element(Q) == zP && return Q
    end
    nothing
end

function _standard_prefix(s::StandardBraid, x::Braid)
    isone(s) && return true
    infimum(x) > 0 && return true
    infimum(x) < 0 && return false
    nf = left_normal_form(x)
    isempty(nf.factors) && return false
    left_gcd_standard(s, StandardBraid(first(nf.factors))) == s
end

"""Conjugate a standard parabolic subgroup by a braid: `P^α = α⁻¹Pα`.

Returns `nothing` when the resulting parabolic subgroup is not standard.
Lemmas 27–28 of the CRS paper use positivity and prefix extraction of `z_P`.
"""
function act_on_parabolic(P::StandardParabolic, α::Braid)
    nstrands(P) == nstrands(α) || throw(DimensionMismatch("parabolic and braid have different strand counts"))
    nf = left_normal_form(α)
    Q = flip_parabolic(P, nf.delta_power)
    zQ = Δ(α.group)^(-nf.delta_power) * central_element(P) * Δ(α.group)^nf.delta_power
    candidates = standard_parabolics(α.group)

    for factor in nf.factors
        s = StandardBraid(factor)
        si = α.group(s)
        zQ = inv(si) * zQ * si
        zQ.delta_power < 0 && return nothing
        # Theorem 26 and Lemma 27 identify the standard parabolic by its
        # positive central element. Verifying the matching z_Q is more robust
        # than relying on the optimized prefix shortcut alone.
        Q = _braid_from_parabolic(Q, candidates, zQ)
        Q === nothing && return nothing
    end
    Q
end

adjacent(a::StandardParabolic, b::StandardParabolic) = begin
    nstrands(a) == nstrands(b) || throw(DimensionMismatch("parabolic subgroups have different strand counts"))
    issubset(a, b) || issubset(b, a) || central_element(a)*central_element(b) == central_element(b)*central_element(a)
end

struct ParabolicSystem
    curves::Vector{StandardParabolic}
    function ParabolicSystem(curves::AbstractVector{StandardParabolic}; check_adjacent=true)
        all(c -> nstrands(c) == nstrands(first(curves)), curves) ||
            throw(ArgumentError("a reduction system must have a common strand count"))
        unique_curves = sort(unique(curves); by=c -> (c.first, c.last, c.strands))
        check_adjacent && !isempty(unique_curves) && for i in 1:length(unique_curves), j in i+1:length(unique_curves)
            adjacent(unique_curves[i], unique_curves[j]) ||
                throw(ArgumentError("curves are not an adjacent reduction simplex"))
        end
        new(unique_curves)
    end
end

ParabolicSystem(B::BraidGroup) = ParabolicSystem(StandardParabolic[])
ParabolicSystem(P::StandardParabolic) = ParabolicSystem([P])
ParabolicSystem() = ParabolicSystem(StandardParabolic[]; check_adjacent=false)
nstrands(S::ParabolicSystem) = isempty(S.curves) ? 0 : nstrands(first(S.curves))
Base.length(S::ParabolicSystem) = length(S.curves)
Base.isempty(S::ParabolicSystem) = isempty(S.curves)
dimension(S::ParabolicSystem) = length(S) - 1
Base.iterate(S::ParabolicSystem, args...) = iterate(S.curves, args...)
Base.in(P::StandardParabolic, S::ParabolicSystem) = P in S.curves
Base.hash(S::ParabolicSystem, h::UInt) = hash(Tuple(S.curves), h)
Base.isequal(a::ParabolicSystem, b::ParabolicSystem) = a.curves == b.curves
Base.:(==)(a::ParabolicSystem, b::ParabolicSystem) = a.curves == b.curves
Base.intersect(a::ParabolicSystem, b::ParabolicSystem) =
    ParabolicSystem(intersect(a.curves, b.curves))

function Base.union(a::ParabolicSystem, b::ParabolicSystem)
    ParabolicSystem(vcat(a.curves, b.curves))
end

function Base.show(io::IO, S::ParabolicSystem)
    print(io, "{", join(repr.(S.curves), ", "), "}")
end

function _commuting_systems(a::ParabolicSystem, b::ParabolicSystem)
    all(x -> all(y -> adjacent(x, y), b.curves), a.curves)
end

function act_on_system(S::ParabolicSystem, α::Braid)
    result = StandardParabolic[]
    for P in S.curves
        Q = act_on_parabolic(P, α)
        Q === nothing && return nothing
        push!(result, Q)
    end
    ParabolicSystem(result)
end

"""The standard full orbit of one parabolic subgroup, if it is a simplex."""
function parabolic_orbit(P::StandardParabolic, α::Braid)
    vertices = StandardParabolic[P]
    current = P
    while true
        Q = act_on_parabolic(current, α)
        Q === nothing && return nothing
        Q == P && return vertices
        Q in vertices && return nothing
        all(R -> adjacent(Q, R), vertices) || return nothing
        push!(vertices, Q)
        current = Q
    end
end

"""Standard reduction simplices for a braid, using CRS Algorithm 1."""
function standard_reduction_simplices(α::Braid; maximal_only=false)
    remaining = standard_parabolics(α.group)
    orbits = ParabolicSystem[]
    while !isempty(remaining)
        P = popfirst!(remaining)
        orbit = parabolic_orbit(P, α)
        orbit === nothing && continue
        S = ParabolicSystem(orbit)
        push!(orbits, S)
        filter!(Q -> !(Q in S), remaining)
    end

    cliques = ParabolicSystem[]
    function grow(current::ParabolicSystem, allowed::Vector{Int})
        push!(cliques, current)
        for (position, i) in enumerate(allowed)
            next = union(current, orbits[i])
            remaining_indices = allowed[position+1:end]
            compatible = filter(j -> _commuting_systems(next, orbits[j]), remaining_indices)
            grow(next, compatible)
        end
    end

    if isempty(orbits)
        push!(cliques, ParabolicSystem())
    else
        grow(ParabolicSystem(), collect(1:length(orbits)))
    end

    maximal_only || return cliques
    return [candidate for candidate in cliques
            if !any(other -> length(candidate) < length(other) && candidate.curves ⊆ other.curves, cliques)]
end

maximal_standard_reduction_simplices(α::Braid) =
    standard_reduction_simplices(α; maximal_only=true)
